async () => {
  const inp = document.querySelector('#twotabsearchtextbox');
  inp.focus();
  inp.value = 'queen size hypoallergenic memory foam mattress topper';
  inp.dispatchEvent(new Event('input', {bubbles:true}));
  document.querySelector('#nav-search-submit-button').click();
  return 'search submitted';
}

() => {
  // Find all filter sections in the sidebar
  const sections = document.querySelectorAll('[id*="filter"]');
  const result = {};
  document.querySelectorAll('.a-section').forEach(sec => {
    const heading = sec.querySelector('h3, .a-text-bold, span');
    if (heading) {
      const text = heading.textContent.trim();
      if (text.length < 50) result[text] = sec.textContent.slice(0, 500);
    }
  });
  return result;
}

() => {
  // Set the lower bound of price slider to $50 (slider position)
  const lowerSlider = document.getElementById('p_36/range-slider_slider-item_lower-bound-slider');
  const upperSlider = document.getElementById('p_36/range-slider_slider-item_upper-bound-slider');
  if (lowerSlider) {
    // $50 maps to slider value (50-22)/(100-22) * 44 = 15.79
    lowerSlider.value = 16;
    lowerSlider.dispatchEvent(new Event('change', {bubbles: true}));
    lowerSlider.dispatchEvent(new Event('input', {bubbles: true}));
  }
  return { lowerVal: lowerSlider ? lowerSlider.value : null, upperVal: upperSlider ? upperSlider.value : null };
}
